{"implementation": "def solve(case):
    threshold = case['threshold']
    calls = case['calls']
    diagnostics = []
    accepted_call_ids = []
    for c in calls:
        call_id = c['call_id']
        gain = (c['loss_without_call'] - c['loss_with_call']) / c['prediction_tokens']
        accepted = (gain >= threshold) and c['parseable']
        diagnostics.append({
            'accepted': accepted,
            'call_id': call_id,
            'normalized_gain': gain
        })
        if accepted:
            accepted_call_ids.append(call_id)
    return {
        'accepted_call_ids': accepted_call_ids,
        'diagnostics': diagnostics
    }"}
